    if (!newSegment) exit(1);
    snake->segments = newSegment;
    snake->segments[snake->segmentCount].x = headX;
    snake->segments[snake->segmentCount].y = headY;
    snake->segments[snake->segmentCount].texture = snake->segments[0].texture;
    snake->segmentCount++;

    // Remove tail if not eating
    if (headX != food->x || headY != food->y) {
        for (int i = snake->segmentCount - 1; i > 0; i--) {
            snake->segments[i].x = snake->segments[i - 1].x;
            snake->segments[i].y = snake->segments[i - 1].y;
